    "《人類的黎明》：從西元前 10,000 年的狩獵採集開始": "\"मानवता की सुबह\": 10,000 ईसा पूर्व शिकारी-संग्राहकों से शुरू करें",
    "《人類的黎明》：每條世界線都不一樣（種子已記錄在「系統」頁的開發者資訊）": "\"मानवता की सुबह\": हर समयरेखा अलग है (सीड सिस्टम पृष्ठ की डेवलपर जानकारी में दर्ज है)",
    "「{0}」世界上還沒有人完成，且{1}具備前置科技": "विश्व में अभी तक किसी ने \"{0}\" पूरा नहीं किया, और {1} के पास पूर्व-आवश्यकताएँ हैं",
    "「{0}」在這條世界線沒有發生": "\"{0}\" इस समयरेखा में नहीं हुआ",
    "「{0}」已有國家掌握，且{1}具備前置科技": "\"{0}\" किसी देश को पहले से ज्ञात है, और {1} के पास पूर्व-आवश्यकताएँ हैं",
    "「{0}」是怎麼來的？": "\"{0}\" कहाँ से आया?",
    "「{0}」的前置技術與地理條件都具備": "\"{0}\" की पूर्व-आवश्यकताएँ और भूगोल तैयार हैं",
    "「{0}」脫離{1}，成為獨立政治實體。": "\"{0}\" {1} से अलग होकर स्वतंत्र राजनीतिक इकाई बना।",
    "「{0}」解散": "\"{0}\" भंग",
    "「備份存檔」會把這個世界存成一個檔案放到你的裝置上；換手機、清除瀏覽器資料之前，或想把世界分享給朋友時使用。": "\"बैकअप सेव\" इस विश्व को आपके डिवाइस पर फ़ाइल के रूप में सहेजता है; फ़ोन बदलने, ब्राउज़र डेटा मिटाने से पहले या दोस्तों के साथ अपना विश्व साझा करने के लिए इसका उपयोग करें।",
    "「如果」平行世界：{0}。": "\"क्या होता अगर?\" समानांतर विश्व: {0}।",
    "「沒有你的世界」：同一個種子、不重播你的介入重跑一次，比較哪個世界先毀滅": "\"आपके बिना विश्व\": उसी सीड से आपके हस्तक्षेप के बिना दोबारा चलाएँ और देखें कौन-सा विश्व पहले ख़त्म होता है",
    "「沒有國家」與「允許戰爭」互相衝突：沒有國家時不存在國家間戰爭。": "\"कोई राज्य नहीं\" का \"युद्ध की अनुमति\" से टकराव है: राज्य न हों तो राज्यों के बीच युद्ध भी नहीं।",
    "「沒有貨幣」與「存在資本主義」互相衝突：資本主義需要以貨幣計價的資本市場。": "\"कोई मुद्रा नहीं\" का \"पूँजीवाद मौजूद\" से टकराव है: पूँजीवाद को मुद्रा में मूल्य वाले पूँजी बाज़ार चाहिए।",
    "「直接死亡」是發生當下的死亡；「之後的死亡」是它留下的長期影響（臨界點的額外升溫、核子寒冬）在之後每年多造成的死亡，依公式拆分。": "\"प्रत्यक्ष मौतें\" उस समय की मौतें हैं; \"बाद की मौतें\" स्थायी प्रभावों (टिपिंग पॉइंट से अतिरिक्त तापन, परमाणु शीत) से बाद के वर्षों में हुई अतिरिक्त मौतें हैं, जिन्हें सूत्र से अलग किया गया है।",
    "「讀取備份」選那個檔案就能回到這個世界。": "इस विश्व में लौटने के लिए \"बैकअप लोड करें\" में वह फ़ाइल चुनें।",
    "」可以追查），每場災難都是事件，可以用「如果？": "\" बटन से खोजा जा सकता है), और हर आपदा एक घटना है जिसे \"क्या होता अगर?",
    "」平行世界重跑時，也會在同一個時間重播這次干預。": "\" समानांतर विश्व दोबारा चलाने पर यह हस्तक्षेप उसी समय दोहराया जाता है।",
    "」平行世界重跑時，也會在同一個月份重播這次干預。": "\" समानांतर विश्व दोबारा चलाने पर यह हस्तक्षेप उसी महीने दोहराया जाता है।",
    "」改寫。": "\" अभी नहीं।",
    "」改寫它沒有發生。": "\" से ऐसे लिखा जा सकता है मानो कभी हुई ही न हो।",
    "」改寫（每一項都能點開追查原因）": "\" पुनर्लेखन (हर एक पर टैप करके कारण देखें)",
    "」改寫，看看世界會在什麼時候、因為什麼終結。": "\" से पुनर्लेखन करें, और देखें विश्व कब और क्यों समाप्त होता है।",
    "」與完整紀錄）。": "\" और पूरा अभिलेख)।",
