    "世界允許國家間戰爭": "विश्व राज्यों के बीच युद्ध की अनुमति देता है",
    "世界出現重大變化時（戰爭、革命、災難、人口或經濟劇變……），這裡會刊出當年影響最大的最多 3 則頭條，每一則都能點開追查原因；其餘的事收進下方的年度摘要。": "जब विश्व में बड़ा बदलाव हो (युद्ध, क्रांतियाँ, आपदाएँ, जनसंख्या या अर्थव्यवस्था में उथल-पुथल…), तो वर्ष की अधिकतम 3 सबसे अहम सुर्खियाँ यहाँ दिखती हैं, हर एक पर टैप कर कारण देखें; बाकी नीचे वार्षिक सारांश में जाता है।",
